import UIKit
@objc(SecureScreen) class SecureScreen: CDVPlugin { var blurView:UIVisualEffectView?; @objc(enableScreenshotProtection:) func enableScreenshotProtection(command:CDVInvokedUrlCommand){let r=CDVPluginResult(status:CDVCommandStatus_OK);commandDelegate.send(r, callbackId: command.callbackId)} @objc(disableScreenshotProtection:) func disableScreenshotProtection(command:CDVInvokedUrlCommand){let r=CDVPluginResult(status:CDVCommandStatus_OK);commandDelegate.send(r, callbackId: command.callbackId)} @objc(enableAppSwitcherBlur:) func enableAppSwitcherBlur(command:CDVInvokedUrlCommand){NotificationCenter.default.addObserver(self, selector:#selector(addBlur), name:UIApplication.willResignActiveNotification, object:nil);NotificationCenter.default.addObserver(self, selector:#selector(removeBlur), name:UIApplication.didBecomeActiveNotification, object:nil);let r=CDVPluginResult(status:CDVCommandStatus_OK);commandDelegate.send(r, callbackId: command.callbackId)} @objc(disableAppSwitcherBlur:) func disableAppSwitcherBlur(command:CDVInvokedUrlCommand){NotificationCenter.default.removeObserver(self);let r=CDVPluginResult(status:CDVCommandStatus_OK);commandDelegate.send(r, callbackId: command.callbackId)} @objc func addBlur(){guard blurView == nil else{return}; let blur=UIVisualEffectView(effect:UIBlurEffect(style:.light)); blur.frame=UIScreen.main.bounds; UIApplication.shared.windows.first?.addSubview(blur); blurView=blur} @objc func removeBlur(){blurView?.removeFromSuperview(); blurView=nil}}